    n = len(s)
    dp = [[0] * n for _ in range(n)]
    res = 0

    for i in range(n):
        dp[i][i] = 1
        res += 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 1
            else:
                dp[i][j] = 1
            res += dp[i][j]

